import { mkdir, writeFile } from 'node:fs/promises';
import { execFileSync } from 'node:child_process';
import path from 'node:path';
import { fileURLToPath } from 'node:url';
import {
  julySampleAvailable,
  loadJulySample,
} from '../tests/helpers/july-sample.ts';
import { exportWorkbook } from '../lib/reconciliation/io.ts';

const project = path.resolve(
  path.dirname(fileURLToPath(import.meta.url)),
  '..',
);
if (!(await julySampleAvailable()))
  throw new Error('Original July files are required; set MIZAN_SAMPLE_DIR.');
// The output is a snapshot generated by the application's own exporter. The
// original financial files are neither copied nor bundled into the repository.
execFileSync(
  process.execPath,
  [
    '--experimental-strip-types',
    '--test',
    'tests/july-sample-regression.test.ts',
  ],
  {
    cwd: project,
    env: process.env,
    stdio: 'inherit',
  },
);
const output =
  process.env.MIZAN_JULY_OUTPUT_DIR ||
  path.resolve(project, '../mizan-july-verified');
await mkdir(output, { recursive: true });
for (const extension of ['xlsx', 'pdf']) {
  const { files, result } = await loadJulySample(extension);
  const bytes = await exportWorkbook(result, files, {
    checked: false,
    name: '',
    notes: '',
  });
  const filename = path.join(
    output,
    `mizan-workpaper-july-2026-${extension}-source.xlsx`,
  );
  await writeFile(filename, new Uint8Array(bytes));
  console.log(
    JSON.stringify({
      output: filename,
      source: extension,
      cases: result.caseCounts,
      residualMinor: result.bridge?.residual,
    }),
  );
}
